// Display all players with DOB year in table format
function filterAndExport(jsonData) {
  // Extract the ranking list from the nested structure
  const rankingList = jsonData[0].data.rankingList;
  
  // Create an object with IDs as keys to remove the index column
  const tableData = {};
  rankingList.forEach((item, i) => {
    // Extract the year from the dob field (format: MM/DD/YYYY)
    const dobYear = item.dob.split('/')[2];
    
    // Replace "MAR-" with "MOR-" in the ID
    const modifiedId = item.wtfLicenseId.startsWith('MAR-') 
      ? item.wtfLicenseId.replace('MAR-', 'MOR-')
      : item.wtfLicenseId;
    
    tableData[i + 1] = {
      ID: modifiedId,
      Name: item.name,
      DOB_Year: dobYear,
      Points: item.points
    };
  });
  
  // Print in table format
  console.table(tableData);
  
  console.log(`\nTotal records: ${rankingList.length}`);
}

